"""California: freeways, ramps and cable car tracks in the module's words and in the 3D street view; what in the engine's
traffic and sky is measured, chosen and generated. Run from CA/scout_work/history: python3 -I p13_roads.py"""
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
SC = os.path.join(os.path.dirname(os.path.dirname(HERE)), 'scout')
sys.path.insert(0, os.path.join(SC, 'tools'))
from lib import F
f = F()
f.rep("        const kind = { major: 'main road', alley: 'alley', service: 'service drive' }[st.roadKind] || '';\n        const on = st.mode === 'street' ? (st.road ? `On ${esc(st.road)}${kind ? ' (' + kind + ')' : ''}` : kind === 'alley' ? 'In an alley' : kind ? 'On a ' + kind : 'At street level') : st.mode === 'drone'",
      "        const kind = { major: 'main road', alley: 'alley', service: 'service drive', freeway: 'freeway', ramp: 'freeway ramp' }[st.roadKind] || '';\n        const on = st.mode === 'street' ? (st.road ? `On ${esc(st.road)}${kind ? ' (' + kind + ')' : ''}` : kind === 'alley' ? 'In an alley' : kind ? 'On a ' + kind : 'At street level') : st.mode === 'drone'")
f.rep("freeway: 'freeway', ramp: 'ramp' }[st.roadKind] || '';\n        const carMph", "freeway: 'freeway', ramp: 'freeway ramp' }[st.roadKind] || '';\n        const carMph")
f.rep("Traffic obeys a car-following law, signals and stop signs, and no two cars may occupy the same ground.", "Traffic obeys a car-following law, signals and stop signs, and no two cars may occupy the same ground.${en && en.world && en.world.traffic ? ' On the freeways, how many vehicles pass follows Caltrans\\'s 2024 counts and how fast they go TomTom\\'s weekday hourly average speeds for the metro, at the hour the sun stands at; the share of a day\\'s traffic in each hour, the truck shares by route, and the lanes and limits where the map is silent are chosen; every car, bus, truck and cable car is generated.' : ''}${airKit() ? ' Aircraft fly the real approaches at each airport\\'s hourly rate and the Navy\\'s piers and the landmark bridges stand where they are; every single flight, which ship lies at which pier, the helicopters and the boats are generated.' : ''}")
f.rep("Walk, drive, fly or circle a building. Window grids, cars, signals, sidewalks and rooftop equipment are generated, not observed.", "Walk, drive, fly or circle a building. Window grids, cars, signals, sidewalks and rooftop equipment are generated, not observed. Where the engine carries California's traffic and sky, the counts behind them are measured (Caltrans's 2024 traffic counts on the state highways; TomTom's weekday hourly average speeds for each metro; the airports' runways, approach paths and flights an hour), the hourly share of a day's traffic, truck shares, and lane and speed limit defaults are chosen, and every vehicle, flight, ship and boat is generated.")
f.rep("        ['Scout Engine', 'A WebGL2 renderer written for this page and carried in the file:", "        ['Traffic and aircraft (Scout Engine)', 'Caltrans Traffic Census, 2024 annual average daily traffic on the state highway system; TomTom Traffic Index, weekday hourly average speeds by metro; OpenStreetMap lanes, one way streets, speed limits and bridge layers; airport runways and approach paths from the public airport files. Every vehicle, flight and ship drawn is generated', 'A for the counts, B as used', '2024 to 2026', 'https://dot.ca.gov/programs/traffic-operations/census'],\n        ['Scout Engine', 'A WebGL2 renderer written for this page and carried in the file:")
f.save()

g = F('scout3d.js')
g.rep("    const ROADW = { major: [12, 0.1, 'asphalt'], street: [8.2, 0.09, 'asphalt'],", "    /* a freeway carriageway and a ramp are roads to look at, not to walk: drawn at 12 ft a lane with shoulders where the map\n       gives the lanes (Caltrans's standard lane; the shoulders are a judgment), else at four lanes and one */\n    const ROADW = { freeway: [19.5, 0.1, 'asphalt'], ramp: [6.1, 0.09, 'asphalt'], major: [12, 0.1, 'asphalt'], street: [8.2, 0.09, 'asphalt'],")
g.rep("      S.roads = list.map(r => ({ name: r.name || '', kind: r.kind, pts: r.pts.map(([la, lo]) => toL(la, lo)) })).filter(r => r.pts.length >= 2);",
      "      S.roads = list.filter(r => r.kind !== 'cable').map(r => ({ name: r.name || '', kind: r.kind, lanes: +r.lanes || 0, pts: r.pts.map(([la, lo]) => toL(la, lo)) })).filter(r => r.pts.length >= 2);   /* a cable car track is not a street */")
g.rep("const spec = ROADW[r.kind] || ROADW.street, B = by[r.kind] = by[r.kind] || batch(); ribbon(B, r.pts, spec[0], spec[1], spec[2] === 'asphalt' ? 4 : 3); });",
      "const spec = ROADW[r.kind] || ROADW.street, B = by[r.kind] = by[r.kind] || batch(), w = (r.kind === 'freeway' || r.kind === 'ramp') && r.lanes > 0 ? r.lanes * 3.66 + (r.kind === 'freeway' ? 4.9 : 2.4) : spec[0]; ribbon(B, r.pts, w, spec[1], spec[2] === 'asphalt' ? 4 : 3); });")
g.save()
